/**
 * Every name a screen may ask for: the art above, and the plain names the
 * app speaks in for the pieces onboarding first named by what they show.
 * An alias points at the same string, so it costs no bytes.
 */
export const FLUENT_ICONS = {
  ...ART,
  /** 🧘 Mobility, stretching. */
  stretch: ART.lotus,
  /** 🌅 The morning stretch, the first steps. */
  morning: ART.sunrise,
  /** ⏱️ How long. */
  timer: ART.stopwatch,
  /** 🎯 Aim, "about right". */
  target: ART.bullseye,
  /** 🏃 A run. */
  run: ART.personRunning,
  /** 👟 A shoe, after a run. */
  shoe: ART.runningShoe,
} satisfies Record<string, string>;

export type FluentName = keyof typeof FLUENT_ICONS;
